export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const m = inputs.mass;

  const tApex = u / g;
  const t = Math.min(time, 2 * tApex);
  const yVal = Math.max(0, u * t - 0.5 * g * t * t);
  const vVal = u - g * t;
  const aVal = -g;
  const fVal = m * g;

  const isAtTop = Math.abs(t - tApex) < 0.015;
  let motionState = "Rising";
  if (t <= 0.001) motionState = "Ready to toss";
  else if (isAtTop) motionState = "At the top";
  else if (t > tApex && yVal > 0.001) motionState = "Falling";
  else if (t >= 2 * tApex - 0.001 || yVal <= 0.001) motionState = "Back at launch height";

  const leftPanel = sdk.panel({
    x: 20,
    y: 30,
    w: 280,
    h: 380,
    title: "The motion",
    state: motionState,
    id: "lane.motion"
  });

  const axisY = sdk.axis("axis.y", {
    x: 80,
    y: 370,
    length: 300,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  });

  const ballPixelY = 370 - (yVal / 2.2) * 300;
  const ballPixelX = 140;

  const ball = sdk.circle("ball.toss", ballPixelX, ballPixelY, 24);

  const vecV = sdk.vector("vec.v", { x: ballPixelX + 24, y: ballPixelY }, {
    value: vVal,
    direction: "up",
    scale: 18,
    label: "v"
  });

  const vecA = sdk.vector("vec.a", { x: ballPixelX - 24, y: ballPixelY }, {
    value: aVal,
    direction: "up",
    scale: 18,
    label: "a"
  });

  const calloutLines = [
    "v = " + vVal.toFixed(2) + " m/s",
    "a = " + aVal.toFixed(1) + " m/s²",
    "Fg = " + fVal.toFixed(1) + " N"
  ];
  const callout = sdk.callout(ballPixelX + 65, ballPixelY - 30, calloutLines, {
    id: "callout.toss"
  });

  const rightPanel = sdk.panel({
    x: 320,
    y: 30,
    w: 300,
    h: 380,
    title: "Velocity over time",
    state: "Slope a = -g",
    id: "lane.graph"
  });

  const tMax = 1.8;
  const sampleCount = 24;
  const points = [];
  for (let i = 0; i <= sampleCount; i++) {
    const st = (i / sampleCount) * tMax;
    const sv = u - g * st;
    points.push({ x: st, y: sv });
  }

  const curMarker = { x: t, y: vVal, label: "v(t)" };

  const vtPlot = sdk.plot("plot.vt", {
    x: 340,
    y: 65,
    w: 260,
    h: 320,
    axes: {
      x: { label: "Time", min: 0, max: tMax, unit: "s" },
      y: { label: "Velocity", min: -5.5, max: 5.5, unit: "m/s" }
    },
    series: [
      {
        label: "v(t)",
        kind: "line",
        points: points
      }
    ],
    marker: curMarker
  });

  const objects = [
    ...leftPanel,
    axisY,
    ball,
    ...vecV,
    ...vecA,
    ...callout,
    ...rightPanel,
    vtPlot
  ];

  const quantities = {
    launchSpeed: u,
    gravity: g,
    mass: m,
    apexTime: tApex,
    apexHeight: (u * u) / (2 * g),
    height: yVal,
    velocity: vVal,
    acceleration: aVal,
    force: fVal
  };

  const readouts = [
    { id: "velocity", value: Number(vVal.toFixed(2)) },
    { id: "acceleration", value: Number(aVal.toFixed(2)) },
    { id: "force", value: Number(fVal.toFixed(2)) },
    { id: "motionState", value: motionState }
  ];

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts
    },
    quantities
  };
}
